trigger folders_thread_visibility_au: CREATE TRIGGER folders_thread_visibility_au AFTER UPDATE OF folder_type ON folders BEGIN UPDATE thread_folders SET visible = CASE WHEN LOWER(TRIM(new.folder_type)) = 'inbox' THEN COALESCE((SELECT workflow_state NOT IN ('aside', 'done', 'snoozed') FROM threads WHERE id = thread_id), 0) ELSE 1 END WHERE folder_id = new.id; END
trigger message_addresses_ad: CREATE TRIGGER message_addresses_ad AFTER DELETE ON messages BEGIN DELETE FROM message_addresses WHERE message_id = old.id; END
trigger message_addresses_ai: CREATE TRIGGER message_addresses_ai AFTER INSERT ON messages BEGIN INSERT INTO message_addresses(message_id, thread_id, email) SELECT m.id, m.thread_id, LOWER(TRIM(address)) FROM messages m JOIN ( SELECT id, from_address AS address FROM messages WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(to_addresses, '[]')) j WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(cc_addresses, '[]')) j WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(bcc_addresses, '[]')) j WHERE messages.id = new.id ) a ON a.id = m.id WHERE TRIM(address) <> '' ON CONFLICT(message_id, email) DO NOTHING; END
trigger message_addresses_au: CREATE TRIGGER message_addresses_au AFTER UPDATE OF id, thread_id, from_address, to_addresses, cc_addresses, bcc_addresses ON messages BEGIN DELETE FROM message_addresses WHERE message_id = old.id; INSERT INTO message_addresses(message_id, thread_id, email) SELECT m.id, m.thread_id, LOWER(TRIM(address)) FROM messages m JOIN ( SELECT id, from_address AS address FROM messages WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(to_addresses, '[]')) j WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(cc_addresses, '[]')) j WHERE messages.id = new.id UNION ALL SELECT messages.id, j.value FROM messages, json_each(COALESCE(bcc_addresses, '[]')) j WHERE messages.id = new.id ) a ON a.id = m.id WHERE TRIM(address) <> '' ON CONFLICT(message_id, email) DO NOTHING; END
trigger message_cc_fts_ad: CREATE TRIGGER message_cc_fts_ad AFTER DELETE ON messages BEGIN DELETE FROM message_cc_fts WHERE rowid = old.rowid; END
trigger message_cc_fts_ai: CREATE TRIGGER message_cc_fts_ai AFTER INSERT ON messages BEGIN INSERT INTO message_cc_fts (rowid, cc_addresses) VALUES (new.rowid, new.cc_addresses); END
trigger message_cc_fts_au: CREATE TRIGGER message_cc_fts_au AFTER UPDATE OF cc_addresses ON messages BEGIN DELETE FROM message_cc_fts WHERE rowid = old.rowid; INSERT INTO message_cc_fts (rowid, cc_addresses) VALUES (new.rowid, new.cc_addresses); END
trigger message_search_projection_ad: CREATE TRIGGER message_search_projection_ad AFTER DELETE ON messages BEGIN DELETE FROM message_search_projection WHERE message_rowid = old.rowid; END
trigger message_search_projection_ai: CREATE TRIGGER message_search_projection_ai AFTER INSERT ON messages BEGIN INSERT INTO message_search_projection (message_rowid, message_id, thread_id, account_id, date) VALUES (new.rowid, new.id, new.thread_id, new.account_id, COALESCE(new.date, '')); END
trigger message_search_projection_au: CREATE TRIGGER message_search_projection_au AFTER UPDATE OF id, thread_id, account_id, date ON messages BEGIN INSERT INTO message_search_projection (message_rowid, message_id, thread_id, account_id, date) VALUES (new.rowid, new.id, new.thread_id, new.account_id, COALESCE(new.date, '')) ON CONFLICT(message_rowid) DO UPDATE SET message_id = excluded.message_id, thread_id = excluded.thread_id, account_id = excluded.account_id, date = excluded.date; END
trigger messages_ad: CREATE TRIGGER messages_ad AFTER DELETE ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, subject, body_text, from_name, from_address, to_addresses) VALUES ('delete', old.rowid, old.subject, old.body_text, old.from_name, old.from_address, old.to_addresses); END
trigger messages_ai: CREATE TRIGGER messages_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid, subject, body_text, from_name, from_address, to_addresses) VALUES (new.rowid, new.subject, new.body_text, new.from_name, new.from_address, new.to_addresses); END
trigger messages_au: CREATE TRIGGER messages_au AFTER UPDATE OF subject, body_text, from_name, from_address, to_addresses ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, subject, body_text, from_name, from_address, to_addresses) VALUES ('delete', old.rowid, old.subject, old.body_text, old.from_name, old.from_address, old.to_addresses); INSERT INTO messages_fts(rowid, subject, body_text, from_name, from_address, to_addresses) VALUES (new.rowid, new.subject, new.body_text, new.from_name, new.from_address, new.to_addresses); END
trigger messages_notification_outbox_ai: CREATE TRIGGER messages_notification_outbox_ai AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO notification_outbox (message_id, state, created_at, last_error) SELECT new.id, CASE WHEN reason IS NULL THEN 'pending' ELSE 'dismissed' END, datetime('now'), reason FROM ( SELECT CASE WHEN julianday(COALESCE(new.received_at, new.date)) IS NOT NULL AND julianday(COALESCE(new.received_at, new.date)) < julianday(watermark, '-1 day') THEN '__skip__' WHEN COALESCE(new.is_sent, 0) <> 0 THEN 'filter_own_sent: is_sent' WHEN COALESCE(new.is_draft, 0) <> 0 THEN 'filter_own_sent: is_draft' WHEN NOT EXISTS ( SELECT 1 FROM accounts a WHERE a.id = new.account_id AND a.kind = 'email' AND a.is_active = 1) THEN 'filter_account_inactive: ' || new.account_id WHEN NOT EXISTS ( SELECT 1 FROM folders f WHERE f.id = new.folder_id AND f.account_id = new.account_id AND LOWER(COALESCE(f.folder_type, '')) = 'inbox') THEN 'filter_not_inbox: ' || COALESCE( (SELECT COALESCE(NULLIF(f.folder_type, ''), f.full_path) FROM folders f WHERE f.id = new.folder_id), new.folder_id) WHEN EXISTS ( SELECT 1 FROM accounts a WHERE a.id = new.account_id AND LOWER(TRIM(new.from_address)) = LOWER(TRIM(a.email))) THEN 'filter_own_sent: ' || new.from_address WHEN COALESCE(( SELECT LOWER(TRIM(value)) FROM app_settings WHERE key = 'notifications.enabled'), 'true') NOT IN ('1', 'true', 'yes') THEN 'setting_disabled: notifications.enabled' WHEN COALESCE(( SELECT LOWER(TRIM(value)) FROM app_settings WHERE key = 'notifications.scope'), 'inbox') = 'off' THEN 'setting_disabled: notifications.scope=off' WHEN julianday(COALESCE(new.received_at, new.date)) IS NULL THEN 'filter_no_date: ' || COALESCE(new.received_at, new.date, '(missing)') WHEN julianday(COALESCE(new.received_at, new.date)) < julianday(watermark) THEN 'filter_too_old: ' || COALESCE(new.received_at, new.date, '') || ' < ' || watermark ELSE NULL END AS reason FROM ( SELECT COALESCE( NULLIF((SELECT a.last_sync_at FROM accounts a WHERE a.id = new.account_id), ''), datetime('now', '-15 minutes') ) AS watermark ) ) WHERE reason IS NULL OR reason <> '__skip__'; END
trigger messages_prefix_ad: CREATE TRIGGER messages_prefix_ad AFTER DELETE ON messages BEGIN INSERT INTO messages_prefix_fts(messages_prefix_fts, rowid, subject, body_text, from_name, from_address, to_addresses) SELECT 'delete', old.rowid, old.subject, old.body_text, old.from_name, old.from_address, old.to_addresses WHERE EXISTS ( SELECT 1 FROM message_prefix_indexed WHERE message_rowid = old.rowid); DELETE FROM message_prefix_indexed WHERE message_rowid = old.rowid; END
trigger messages_prefix_ai: CREATE TRIGGER messages_prefix_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_prefix_fts(rowid, subject, body_text, from_name, from_address, to_addresses) VALUES (new.rowid, new.subject, new.body_text, new.from_name, new.from_address, new.to_addresses); INSERT INTO message_prefix_indexed VALUES (new.rowid) ON CONFLICT(message_rowid) DO NOTHING; END
trigger messages_prefix_au: CREATE TRIGGER messages_prefix_au AFTER UPDATE OF subject, body_text, from_name, from_address, to_addresses ON messages BEGIN INSERT INTO messages_prefix_fts(messages_prefix_fts, rowid, subject, body_text, from_name, from_address, to_addresses) SELECT 'delete', old.rowid, old.subject, old.body_text, old.from_name, old.from_address, old.to_addresses WHERE EXISTS ( SELECT 1 FROM message_prefix_indexed WHERE message_rowid = old.rowid); INSERT INTO messages_prefix_fts(rowid, subject, body_text, from_name, from_address, to_addresses) VALUES (new.rowid, new.subject, new.body_text, new.from_name, new.from_address, new.to_addresses); INSERT INTO message_prefix_indexed VALUES (new.rowid) ON CONFLICT(message_rowid) DO NOTHING; END
trigger messages_thread_folders_ad: CREATE TRIGGER messages_thread_folders_ad AFTER DELETE ON messages WHEN old.thread_id IS NOT NULL BEGIN UPDATE thread_folders SET message_count = message_count - 1, unread_count = MAX(unread_count - COALESCE(old.is_read = 0, 0), 0) WHERE folder_id = COALESCE(old.pending_folder_id, old.folder_id) AND thread_id = old.thread_id; DELETE FROM thread_folders WHERE folder_id = COALESCE(old.pending_folder_id, old.folder_id) AND thread_id = old.thread_id AND message_count <= 0; END
trigger messages_thread_folders_ai: CREATE TRIGGER messages_thread_folders_ai AFTER INSERT ON messages WHEN new.thread_id IS NOT NULL BEGIN INSERT INTO thread_folders(folder_id, thread_id, message_count, unread_count, visible) SELECT f.id, new.thread_id, 1, COALESCE(new.is_read = 0, 0), CASE WHEN LOWER(TRIM(f.folder_type)) = 'inbox' THEN COALESCE(t.workflow_state NOT IN ('aside', 'done', 'snoozed'), 0) ELSE 1 END FROM folders f LEFT JOIN threads t ON t.id = new.thread_id WHERE f.id = COALESCE(new.pending_folder_id, new.folder_id) ON CONFLICT(folder_id, thread_id) DO UPDATE SET message_count = message_count + 1, unread_count = unread_count + excluded.unread_count, visible = excluded.visible; END
trigger messages_thread_folders_au: CREATE TRIGGER messages_thread_folders_au AFTER UPDATE OF folder_id, pending_folder_id, thread_id, is_read ON messages WHEN COALESCE(old.pending_folder_id, old.folder_id) IS NOT COALESCE(new.pending_folder_id, new.folder_id) OR old.thread_id IS NOT new.thread_id OR COALESCE(old.is_read = 0, 0) <> COALESCE(new.is_read = 0, 0) BEGIN INSERT INTO thread_folders(folder_id, thread_id, message_count, unread_count, visible) SELECT f.id, new.thread_id, 1, COALESCE(new.is_read = 0, 0), CASE WHEN LOWER(TRIM(f.folder_type)) = 'inbox' THEN COALESCE(t.workflow_state NOT IN ('aside', 'done', 'snoozed'), 0) ELSE 1 END FROM folders f LEFT JOIN threads t ON t.id = new.thread_id WHERE new.thread_id IS NOT NULL AND f.id = COALESCE(new.pending_folder_id, new.folder_id) ON CONFLICT(folder_id, thread_id) DO UPDATE SET message_count = message_count + 1, unread_count = unread_count + excluded.unread_count, visible = excluded.visible; UPDATE thread_folders SET message_count = message_count - 1, unread_count = MAX(unread_count - COALESCE(old.is_read = 0, 0), 0) WHERE old.thread_id IS NOT NULL AND folder_id = COALESCE(old.pending_folder_id, old.folder_id) AND thread_id = old.thread_id; DELETE FROM thread_folders WHERE old.thread_id IS NOT NULL AND folder_id = COALESCE(old.pending_folder_id, old.folder_id) AND thread_id = old.thread_id AND message_count <= 0; END
trigger provider_thread_keys_reanchor_before_message_delete: CREATE TRIGGER provider_thread_keys_reanchor_before_message_delete BEFORE DELETE ON messages BEGIN UPDATE provider_thread_keys SET message_id = COALESCE( (SELECT remaining.id FROM messages remaining WHERE remaining.id != OLD.id AND remaining.account_id = OLD.account_id AND remaining.thread_id = OLD.thread_id ORDER BY remaining.rowid DESC LIMIT 1), message_id ) WHERE message_id = OLD.id; -- Without a replacement the unchanged reference cascades with OLD.id. END
trigger thread_folders_ad: CREATE TRIGGER thread_folders_ad AFTER DELETE ON thread_folders BEGIN UPDATE folders SET thread_count = thread_count - old.visible, thread_unread_count = thread_unread_count - (old.visible AND old.unread_count > 0) WHERE id = old.folder_id; END
trigger thread_folders_ai: CREATE TRIGGER thread_folders_ai AFTER INSERT ON thread_folders BEGIN UPDATE folders SET thread_count = thread_count + new.visible, thread_unread_count = thread_unread_count + (new.visible AND new.unread_count > 0) WHERE id = new.folder_id; END
trigger thread_folders_au: CREATE TRIGGER thread_folders_au AFTER UPDATE ON thread_folders BEGIN UPDATE folders SET thread_count = thread_count + new.visible - old.visible, thread_unread_count = thread_unread_count + (new.visible AND new.unread_count > 0) - (old.visible AND old.unread_count > 0) WHERE id = new.folder_id; END
trigger threads_folder_visibility_ad: CREATE TRIGGER threads_folder_visibility_ad AFTER DELETE ON threads BEGIN UPDATE thread_folders SET visible = CASE WHEN (SELECT LOWER(TRIM(folder_type)) FROM folders WHERE id = folder_id) = 'inbox' THEN 0 ELSE 1 END WHERE thread_id = old.id; END
trigger threads_folder_visibility_ai: CREATE TRIGGER threads_folder_visibility_ai AFTER INSERT ON threads BEGIN UPDATE thread_folders SET visible = CASE WHEN (SELECT LOWER(TRIM(folder_type)) FROM folders WHERE id = folder_id) = 'inbox' THEN COALESCE(new.workflow_state NOT IN ('aside', 'done', 'snoozed'), 0) ELSE 1 END WHERE thread_id = new.id; END
trigger threads_folder_visibility_au: CREATE TRIGGER threads_folder_visibility_au AFTER UPDATE OF workflow_state ON threads BEGIN UPDATE thread_folders SET visible = CASE WHEN (SELECT LOWER(TRIM(folder_type)) FROM folders WHERE id = folder_id) = 'inbox' THEN COALESCE(new.workflow_state NOT IN ('aside', 'done', 'snoozed'), 0) ELSE 1 END WHERE thread_id = new.id; END
trigger topic_membership_delete: CREATE TRIGGER topic_membership_delete AFTER DELETE ON topic_items WHEN EXISTS (SELECT 1 FROM topics WHERE id = OLD.topic_id) BEGIN INSERT INTO topic_membership_versions VALUES (OLD.topic_id, OLD.item_type, OLD.item_id, lower(hex(randomblob(16))), OLD.added_at, OLD.added_by) ON CONFLICT(topic_id, item_type, item_id) DO UPDATE SET revision = excluded.revision, added_at = excluded.added_at, added_by = excluded.added_by; END
trigger topic_membership_insert: CREATE TRIGGER topic_membership_insert AFTER INSERT ON topic_items BEGIN INSERT INTO topic_membership_versions VALUES (NEW.topic_id, NEW.item_type, NEW.item_id, lower(hex(randomblob(16))), NEW.added_at, NEW.added_by) ON CONFLICT(topic_id, item_type, item_id) DO UPDATE SET revision = excluded.revision, added_at = excluded.added_at, added_by = excluded.added_by; END
trigger topic_membership_update: CREATE TRIGGER topic_membership_update AFTER UPDATE ON topic_items BEGIN DELETE FROM topic_membership_versions WHERE topic_id = OLD.topic_id AND item_type = OLD.item_type AND item_id = OLD.item_id; INSERT INTO topic_membership_versions VALUES (NEW.topic_id, NEW.item_type, NEW.item_id, lower(hex(randomblob(16))), NEW.added_at, NEW.added_by) ON CONFLICT(topic_id, item_type, item_id) DO UPDATE SET revision = excluded.revision, added_at = excluded.added_at, added_by = excluded.added_by; END
view v_accounts: CREATE VIEW v_accounts AS SELECT a.id AS id, a.kind AS kind, a.provider AS provider, a.email AS email, a.display_name AS display_name, a.color AS color, COALESCE(a.is_active, 0) AS is_active, a.last_sync_at AS last_sync_at, a.created_at AS created_at, a.updated_at AS updated_at FROM accounts a
view v_attachments: CREATE VIEW v_attachments AS SELECT att.id AS id, att.message_id AS message_id, m.thread_id AS thread_id, m.account_id AS account_id, att.filename AS filename, att.content_type AS content_type, COALESCE(att.size, 0) AS size_bytes, COALESCE(att.is_inline, 0) AS is_inline, att.content_id AS content_id, (COALESCE(att.cached_path, att.storage_path) IS NOT NULL) AS is_downloaded, COALESCE(att.cached_path, att.storage_path) AS local_path, att.created_at AS created_at FROM attachments att LEFT JOIN messages m ON m.id = att.message_id
view v_folders: CREATE VIEW v_folders AS SELECT f.id AS id, f.account_id AS account_id, a.email AS account_email, f.name AS name, f.full_path AS full_path, f.folder_type AS folder_type, ( SELECT COUNT(1) FROM messages m WHERE m.folder_id = f.id ) AS message_count, ( SELECT COUNT(1) FROM messages m WHERE m.folder_id = f.id AND COALESCE(m.is_read, 0) = 0 ) AS unread_count, COALESCE(f.sync_enabled, 1) AS sync_enabled, COALESCE(f.sort_order, 0) AS sort_order, f.created_at AS created_at, f.updated_at AS updated_at FROM folders f LEFT JOIN accounts a ON a.id = f.account_id
view v_messages: CREATE VIEW v_messages AS SELECT m.id AS id, m.thread_id AS thread_id, m.account_id AS account_id, a.email AS account_email, m.folder_id AS folder_id, f.name AS folder_name, f.folder_type AS folder_type, m.from_address AS from_address, m.from_name AS from_name, m.to_addresses AS to_addresses, m.cc_addresses AS cc_addresses, m.subject AS subject, m.date AS date, COALESCE(m.is_read, 0) AS is_read, COALESCE(m.is_draft, 0) AS is_draft, COALESCE(m.is_sent, 0) AS is_sent, COALESCE(m.is_starred, 0) AS is_starred, COALESCE(m.has_attachments, 0) AS has_attachments, m.snippet AS snippet, m.body_text AS body_text, (m.body_html IS NOT NULL AND m.body_html <> '') AS has_body_html, m.raw_size AS size_bytes, m.category AS category, m.list_unsubscribe AS list_unsubscribe, m.created_at AS created_at, m.updated_at AS updated_at, m.message_id_header AS message_id_header FROM messages m LEFT JOIN accounts a ON a.id = m.account_id LEFT JOIN folders f ON f.id = m.folder_id
view v_tags: CREATE VIEW v_tags AS SELECT tg.id AS id, tg.name AS name, tg.color AS color, tg.icon AS icon, COALESCE(tg.is_system, 0) AS is_system, COALESCE(tg.sort_order, 0) AS sort_order, ( SELECT COUNT(1) FROM thread_tags WHERE thread_tags.tag_id = tg.id ) AS thread_count FROM tags tg
view v_threads: CREATE VIEW v_threads AS SELECT t.id AS id, t.account_id AS account_id, a.email AS account_email, t.subject AS subject, t.snippet AS snippet, ( SELECT group_concat(email, ', ') FROM ( SELECT DISTINCT CASE WHEN participant.type = 'object' THEN json_extract(participant.value, '$.email') ELSE participant.value END AS email FROM json_each( CASE WHEN json_valid(t.participants) THEN t.participants ELSE '[]' END ) AS participant ) WHERE email IS NOT NULL AND TRIM(email) <> '' ) AS participants, t.participants AS participants_json, COALESCE(t.message_count, 0) AS message_count, COALESCE(t.unread_count, 0) AS unread_count, ( SELECT MIN(m.date) FROM messages m WHERE m.thread_id = t.id ) AS first_message_date, t.last_message_date AS last_message_date, t.workflow_state AS workflow_state, t.workflow_changed_at AS workflow_changed_at, t.snooze_until AS snoozed_until, t.due_date AS due_date, COALESCE(t.is_starred, 0) AS is_starred, COALESCE(t.is_muted, 0) AS is_muted, COALESCE(t.has_attachments, 0) AS has_attachments, COALESCE(t.priority, 0) AS priority, t.category AS category, t.assignee AS assignee, ( SELECT group_concat(name, ', ') FROM ( SELECT tags.name AS name FROM thread_tags JOIN tags ON tags.id = thread_tags.tag_id WHERE thread_tags.thread_id = t.id ORDER BY tags.name COLLATE NOCASE ) ) AS tags, ( SELECT group_concat(topic_id, ',') FROM ( SELECT topic_items.topic_id AS topic_id FROM topic_items WHERE topic_items.item_type = 'thread' AND topic_items.item_id = t.id ORDER BY topic_items.topic_id ) ) AS topic_ids, t.created_at AS created_at, t.updated_at AS updated_at FROM threads t LEFT JOIN accounts a ON a.id = t.account_id
view v_topics: CREATE VIEW v_topics AS SELECT tp.id AS id, tp.name AS name, tp.description AS description, tp.status AS status, tp.color AS color, tp.icon AS icon, tp.due_date AS due_date, ( SELECT COUNT(1) FROM topic_items WHERE topic_items.topic_id = tp.id AND topic_items.item_type = 'thread' ) AS thread_count, ( SELECT COUNT(1) FROM topic_items WHERE topic_items.topic_id = tp.id AND topic_items.item_type = 'message' ) AS message_count, ( SELECT COUNT(1) FROM topic_notes WHERE topic_notes.topic_id = tp.id ) AS note_count, ( SELECT COUNT(1) FROM topic_files WHERE topic_files.topic_id = tp.id ) AS file_count, tp.created_at AS created_at, tp.updated_at AS updated_at FROM topics tp
